mapper.insert:
INSERT INTO mq_outbox (
    event_id, event_type, exchange_name, routing_key, message_body,
    status, retry_count, next_attempt_time, lease_until, last_error,
    create_time, update_time
) VALUES (
    #{eventId}, #{eventType}, #{exchangeName}, #{routingKey}, #{messageBody},
    #{status}, #{retryCount}, #{nextAttemptTime}, #{leaseUntil}, #{lastError},
    #{createTime}, #{updateTime}
)

mapper.select:
SELECT *
FROM mq_outbox
WHERE retry_count < #{maxRetryCount}
  AND (
      status = 0
      OR (status = 3 AND next_attempt_time <= NOW())
      OR (status = 1 AND lease_until <= NOW())
  )
ORDER BY next_attempt_time ASC, id ASC
LIMIT #{limit}
